                      </p>
                    </div>
                    {plan === "free" && (
                      <Button size="sm" asChild className="gap-1.5">
                        <Link href="/pricing">
                          <ArrowUpRight className="h-3.5 w-3.5" /> Upgrade
                        </Link>
                      </Button>
                    )}
                  </div>
                </div>

                {/* Billing History */}
                {billingLoading ? (
                  <div className="space-y-2">
                    {[1, 2, 3].map(i => <div key={i} className="h-10 bg-muted animate-pulse rounded" />)}
                  </div>
                ) : billingHistory && billingHistory.length > 0 ? (
                  <div>
                    <p className="text-xs font-medium text-muted-foreground uppercase tracking-wide mb-2">Payment history</p>
                    <div className="space-y-1">
                      {billingHistory.slice(0, 10).map((invoice, i: number) => (
                        <div key={i} className="flex items-center justify-between py-2 border-b border-border/30 last:border-0">
                          <div>
                            <p className="text-sm">{invoice.description || "Subscription"}</p>
                            <p className="text-xs text-muted-foreground">{new Date(invoice.date).toLocaleDateString()}</p>
                          </div>
                          <div className="text-right">
                            <p className="text-sm font-medium">${(invoice.amount / 100).toFixed(2)}</p>
                            <Badge variant={invoice.status === "paid" ? "default" : "secondary"} className="text-xs h-4">
                              {invoice.status}
                            </Badge>
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                ) : (
                  <div className="text-center py-6 border border-dashed border-border rounded-lg">
                    <CreditCard className="h-7 w-7 text-muted-foreground/40 mx-auto mb-2" />
                    <p className="text-sm text-muted-foreground">No billing history yet</p>
                    {plan === "free" && (
                      <Button size="sm" variant="outline" asChild className="mt-3">
                        <Link href="/pricing">View plans</Link>
                      </Button>
                    )}
                  </div>
                )}
              </TabsContent>
            </Tabs>
          </div>

          {/* Right: Quick Start + Resources */}
          <div className="space-y-4">
            <QuickStartChecklist hasApiKey={hasApiKey} hasUsage={hasUsage} />

            <Card className="border-border/50">
              <CardHeader className="pb-3">
                <CardTitle className="text-base font-semibold">Resources</CardTitle>
              </CardHeader>
              <CardContent className="space-y-2">
                {[
                  { icon: BookOpen, label: "Documentation", href: "/docs", desc: "API reference & guides" },
                  { icon: Code2, label: "Quickstart", href: "/docs/quickstart", desc: "First call in 5 minutes" },
                  { icon: Zap, label: "MCP Integration", href: "/docs/mcp-integration", desc: "Connect to Claude & GPT" },
                  { icon: Activity, label: "Free scan", href: "/scan", desc: "Scan any URL for free" },
                ].map(({ icon: Icon, label, href, desc }) => (
                  <Link key={href} href={href} className="flex items-center gap-3 p-2 rounded-md hover:bg-muted/50 transition-colors group">
                    <Icon className="h-4 w-4 text-muted-foreground group-hover:text-primary transition-colors shrink-0" />
                    <div className="min-w-0">
                      <p className="text-sm font-medium">{label}</p>
                      <p className="text-xs text-muted-foreground">{desc}</p>
                    </div>
                    <ChevronRight className="h-3.5 w-3.5 text-muted-foreground/40 ml-auto shrink-0 group-hover:text-primary transition-colors" />
                  </Link>
                ))}
              </CardContent>
            </Card>

            {plan === "free" && (
              <Card className="border-primary/20 bg-primary/5">
                <CardContent className="pt-4">
                  <p className="text-sm font-semibold">Upgrade to Developer</p>
                  <p className="text-xs text-muted-foreground mt-1">1,000 checks/month, all purpose-built governance checks, no feature gates.</p>
                  <Button size="sm" className="w-full mt-3 gap-1.5" asChild>
                    <Link href="/pricing">
                      <ArrowUpRight className="h-3.5 w-3.5" /> See plans from $49/mo
                    </Link>
                  </Button>
                </CardContent>
              </Card>
            )}
          </div>
        </div>
      </div>

      <ApiKeyRevealDialog apiKey={revealedKey} onClose={() => setRevealedKey(null)} />
    </div>
  );
}

