2	//
3	// THE EPISODE THAT CAUSED THIS. A worker was asked to build a Claude write path
4	// into the live Operator Lab. It searched ITS OWN tool surface, found no Lab
5	// tool, found the one candidate MCP server unauthenticated, and emitted
6	// `blocked`. The doctrine requiring capability exhaustion already existed. It
7	// did not fire, because nothing sat on the path between the conclusion and the
8	// operator.
9	//
10	// An exhaustive search of the SYSTEM — not the worker's local surface — then
11	// found `observe_interaction` and `gate_outbound_inference`, produced a real
12	// Claude-attributed control-plane event, and moved live readiness from
13	// ChatGPT-only to Claude + ChatGPT. The capability was never absent. It was
14	// absent FROM ONE WORKER'S VIEW, and the worker treated that as the same thing.
15	//
16	// So the defect is not missing doctrine. It is doctrine with no enforcement
17	// surface — the same failure shape as publication authority before it was
18	// wired, and as every "rule that is only a model" this substrate has found.
19	//
20	// THE RULE: a worker may not decide for itself that it has exhausted its
21	// options. Concession requires evidence, and incomplete evidence means keep
22	// searching.
23	
24	export const CONCESSION_CLASSES = [
25	  "blocked", "cannot", "should_pause", "needs_manual",
26	  "sam_hands", "infeasible", "out_of_scope_capability",
27	];
28	
29	export const VERDICTS = ["continue_search", "concession_allowed"];
30	
31	// Phrases that ARE a concession regardless of how they are dressed. The gate
32	// must not be escapable by wording, because the worker writing the wording is
33	// the party the gate constrains.
34	export const CONCESSION_MARKERS = [
35	  /\bblocked\b/i, /\bcannot\b/i, /\bcan['’]t\b/i, /\bunable to\b/i,
36	  /\bno (?:way|path|route|mechanism)\b/i, /\bnot possible\b/i,
37	  /\bimpossible\b/i, /\bawait(?:ing)? (?:your|operator|human)\b/i,
38	  /\bneeds? (?:manual|human|operator)\b/i, /\bout of (?:my )?(?:scope|reach)\b/i,
39	  /\bI (?:don['’]t|do not) have (?:access|a tool|the ability)\b/i,
40	  /\bpaus(?:e|ing)\b/i, /\bhold(?:ing)? for\b/i,
41	];
42	
43	/** Does this output concede? Detection is deliberately broad. */
44	export function isConcession(text = "") {
45	  const hits = CONCESSION_MARKERS.filter((re) => re.test(text));
46	  return { conceding: hits.length > 0, matched: hits.map(String) };
47	}
48	
49	// The eight fields. Absence is not "unknown" here — it is INSUFFICIENT, and
50	// insufficient means keep going.
51	export const REQUIRED_EVIDENCE = [
52	  "proposed_concession",
53	  "concession_class",
54	  "available_interfaces",
55	  "paths_attempted",
56	  "attempt_results",
57	  "workaround_classes_considered",
58	  "why_each_viable_workaround_failed",
59	  "other_surface_may_hold_capability",
60	];
61	
62	/**
63	 * The gate. Returns `continue_search` unless the evidence is complete AND the
64	 * cross-surface question has actually been answered.
65	 *
66	 * @param {object} ev  the eight fields
67	 * @param {object} opts
68	 *   attemptedSignatures: paths already tried in earlier rounds (loop control)
69	 *   round: which exhaustion round this is
70	 */
71	export function concessionGate(ev = {}, opts = {}) {
72	  const round = opts.round ?? 1;
73	  const maxRounds = opts.maxRounds ?? 3;
74	  const missing = REQUIRED_EVIDENCE.filter((f) => {
75	    const v = ev[f];
76	    if (v === undefined || v === null) return true;
77	    if (Array.isArray(v)) return v.length === 0;
78	    if (typeof v === "string") return v.trim().length === 0;
79	    return false;
80	  });
81	
82	  const reasons = [];
83	  let verdict = "concession_allowed";
84	  const block = (r) => { verdict = "continue_search"; reasons.push(r); };
85	
86	  if (missing.length) block(`incomplete exhaustion evidence — missing: ${missing.join(", ")}`);
87	
88	  if (!CONCESSION_CLASSES.includes(ev.concession_class))
89	    block(`concession_class '${ev.concession_class}' is not a registered class`);
90	
91	  // THE FIELD THE REAL FAILURE TURNED ON. A worker whose local surface lacks a
92	  // tool has established local absence, never system absence. This must be
93	  // answered with an enumeration, not an intuition.
94	  const cross = ev.other_surface_may_hold_capability;
95	  if (cross && typeof cross === "object") {
96	    if (cross.enumerated !== true)
97	      block("cross-surface capability search was NOT performed — local absence is not system absence");
